// Generates apis/sdk-snippets.json — the "TypeScript (SDK)" code sample shown on every endpoint
// of the API reference, keyed by operationId. Runs before every dev/build (like gen-api-versions).
//
// Source: apis/openapi.json, the alias of the latest spec — the same file the SDK
// (@wrestaurant/sdk, generated by Fern in Inowu/wrestaurant-fern) is built from. Older versions
// share operationIds, so their pages show the same (latest) SDK call.
//
// Mirrors how Fern's TypeScript generator shapes the client:
//   - Sub-client:  x-fern-sdk-group-name — but ONLY when x-fern-sdk-method-name is also present;
//                  Fern ignores a lone group extension. Otherwise the camelCased first tag
//                  (Fern's own fallback, e.g. tag "Endpoints" -> client.endpoints).
//   - Method:      x-fern-sdk-method-name, else the camelCased operationId.
//   - Request:     ONE object with path params + query params + body properties flattened in.
//                  Exception: when the body schema is also referenced outside request bodies
//                  (e.g. reused as a response type), Fern can't inline it and nests it under `body`.
//   - Auth:        X-Api-Key comes from the client constructor, so it is never an argument.
//
// The config can't do this itself: Zudoku bundles it for the browser (no node:fs) and only
// passes the single operation to generateCodeSnippet, not the whole spec.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const apisDir = join(dirname(fileURLToPath(import.meta.url)), "..", "apis");
const spec = JSON.parse(readFileSync(join(apisDir, "openapi.json"), "utf8"));

const SAMPLE_LICENSE_KEY = "DS5D2368HCME4O9X";
const CLIENT_HEADERS = new Set(["x-api-key"]); // set once on the client, not per call
const SCHEMA_REF = "#/components/schemas/";

const lowerFirst = (s) => s.charAt(0).toLowerCase() + s.slice(1);
// Fern camelCases names: "Puntos de venta" -> puntosDeVenta, "id_producto" -> idProducto.
const camel = (s) =>
  lowerFirst(
    s
      .normalize("NFD")
      .replace(/[̀-ͯ]/g, "")
      .split(/[^A-Za-z0-9]+/)
      .filter(Boolean)
      .map((w, i) => (i === 0 ? w : w.charAt(0).toUpperCase() + w.slice(1)))
      .join(""),
  );

const resolve = (schema) => {
  let s = schema;
  for (let guard = 0; s?.$ref && guard < 20; guard++) {
    s = spec.components?.schemas?.[s.$ref.slice(SCHEMA_REF.length)];
  }
  return s ?? {};
};

// Schema names referenced anywhere except directly as an operation's request body.
const referencedOutsideRequestBodies = (() => {
  const names = new Set();
  const collect = (node) => {
    if (!node || typeof node !== "object") return;
    if (typeof node.$ref === "string" && node.$ref.startsWith(SCHEMA_REF)) {
      names.add(node.$ref.slice(SCHEMA_REF.length));
    }
    for (const v of Object.values(node)) collect(v);
  };
  for (const item of Object.values(spec.paths ?? {})) {
    for (const op of Object.values(item)) {
      if (!op || typeof op !== "object") continue;
      const { requestBody, ...rest } = op;
      collect(rest);
      // Nested refs inside an inline body schema still count as "outside".
      for (const media of Object.values(requestBody?.content ?? {})) {
        if (!media.schema?.$ref) collect(media.schema);
      }
    }
  }
  collect(spec.components?.schemas);
  return names;
})();

const placeholder = (schema, name, depth = 0) => {
  const s = resolve(schema);
  if (s.example !== undefined) return s.example;
  if (s.enum?.length) return s.enum[0];
  if (name === "licenseKey") return SAMPLE_LICENSE_KEY;
  switch (s.type) {
    case "integer":
    case "number":
      return 1;
    case "boolean":
      return true;
    case "array":
      return depth > 3 ? [] : [placeholder(s.items, undefined, depth + 1)];
    case "object":
      return depth > 3 ? {} : objectFromRequired(s, depth + 1);
    default:
      if (s.format === "uuid") return "3fa85f64-5717-4562-b3fc-2c963f66afa6";
      if (s.format === "date-time") return "2026-01-01T00:00:00Z";
      if (s.format === "date") return "2026-01-01";
      return name ?? "string";
  }
};

// Required properties; when a schema declares none, all of them (so the sample isn't just {}).
const objectFromRequired = (schema, depth = 0) => {
  const s = resolve(schema);
  const out = {};
  const keys = s.required?.length ? s.required : Object.keys(s.properties ?? {});
  for (const key of keys) {
    out[key] = placeholder(s.properties?.[key], key, depth);
  }
  return out;
};

const camelKeys = (value) => {
  if (Array.isArray(value)) return value.map(camelKeys);
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [/[_-]/.test(k) ? camel(k) : k, camelKeys(v)]));
  }
  return value;
};

const bodyExample = (media) => {
  if (media.example !== undefined) return media.example;
  const first = Object.values(media.examples ?? {})[0];
  if (first?.value !== undefined) return first.value;
  return objectFromRequired(media.schema);
};

// Renders a JS object literal (unquoted identifier keys, 2-space indent).
const IDENT = /^[A-Za-z_$][A-Za-z0-9_$]*$/;
const render = (value, indent = 0) => {
  const pad = "  ".repeat(indent + 1);
  const end = "  ".repeat(indent);
  if (Array.isArray(value)) {
    if (value.length === 0) return "[]";
    return `[\n${value.map((v) => pad + render(v, indent + 1)).join(",\n")},\n${end}]`;
  }
  if (value && typeof value === "object") {
    const entries = Object.entries(value);
    if (entries.length === 0) return "{}";
    const lines = entries.map(([k, v]) => `${pad}${IDENT.test(k) ? k : JSON.stringify(k)}: ${render(v, indent + 1)}`);
    return `{\n${lines.join(",\n")},\n${end}}`;
  }
  return JSON.stringify(value);
};

const snippets = {};
for (const item of Object.values(spec.paths ?? {})) {
  for (const op of Object.values(item)) {
    if (!op?.operationId || !op.responses) continue;

    const explicit = op["x-fern-sdk-group-name"] && op["x-fern-sdk-method-name"];
    const group = explicit ? op["x-fern-sdk-group-name"] : op.tags?.[0] ? camel(op.tags[0]) : null;
    const method = explicit ? op["x-fern-sdk-method-name"] : lowerFirst(op.operationId);

    const args = {};
    for (const p of op.parameters ?? []) {
      if (!p.required || p.in === "cookie" || CLIENT_HEADERS.has(p.name.toLowerCase())) continue;
      args[camel(p.name)] = p.example ?? placeholder(p.schema, p.name);
    }

    const media = op.requestBody?.content?.["application/json"];
    if (media) {
      const body = camelKeys(bodyExample(media));
      const refName = media.schema?.$ref?.slice(SCHEMA_REF.length);
      const flatten =
        body && typeof body === "object" && !Array.isArray(body) && !referencedOutsideRequestBodies.has(refName);
      if (flatten) Object.assign(args, body);
      else args.body = body;
    }

    const call = `client.${group ? `${group}.` : ""}${method}`;
    snippets[op.operationId] = [
      `import { WrestaurantApiClient } from "@wrestaurant/sdk";`,
      ``,
      `const client = new WrestaurantApiClient({`,
      `  apiKey: process.env.WRESTAURANT_API_KEY!, // wrst_live_...`,
      `});`,
      ``,
      `const response = await ${call}(${Object.keys(args).length ? render(args) : ""});`,
      `console.log(response);`,
    ].join("\n");
  }
}

writeFileSync(join(apisDir, "sdk-snippets.json"), JSON.stringify(snippets, null, 2) + "\n");
console.log(`wrote apis/sdk-snippets.json (${Object.keys(snippets).length} operations)`);
